CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, pollar_subject text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallet_bindings (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), address text NOT NULL, wallet_type text NOT NULL, network text NOT NULL CHECK (network='stellar-testnet'), earn_supported boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS assets (network text NOT NULL CHECK (network='stellar-testnet'), code text NOT NULL, issuer text NOT NULL, decimals smallint NOT NULL CHECK (decimals=7), PRIMARY KEY(network,code,issuer));
CREATE TABLE IF NOT EXISTS earn_positions (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), asset_network text NOT NULL, asset_code text NOT NULL, asset_issuer text NOT NULL, shares numeric(30,7) NOT NULL DEFAULT 0, capital_basis numeric(30,7) NOT NULL DEFAULT 0, conservative_value numeric(30,7) NOT NULL DEFAULT 0, realized_earnings numeric(30,7) NOT NULL DEFAULT 0, unrecovered_loss numeric(30,7) NOT NULL DEFAULT 0, observed_ledger bigint, observed_at timestamptz, reconciliation text NOT NULL DEFAULT 'blocked');
CREATE TABLE IF NOT EXISTS journal_entries (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), external_event_id text UNIQUE, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_lines (id uuid PRIMARY KEY, entry_id uuid NOT NULL REFERENCES journal_entries(id), account text NOT NULL, asset_network text NOT NULL, asset_code text NOT NULL, asset_issuer text NOT NULL, amount numeric(30,7) NOT NULL, CHECK (amount <> 0));
CREATE TABLE IF NOT EXISTS policies (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), revision bigint NOT NULL DEFAULT 0, task_cap numeric(30,7) NOT NULL, daily_cap numeric(30,7) NOT NULL, paused boolean NOT NULL DEFAULT false, allowed_provider_ids text[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), title text NOT NULL, brief text NOT NULL, provider_id text NOT NULL, budget numeric(30,7) NOT NULL, recipient text NOT NULL, status text NOT NULL, revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, paid_at timestamptz);
CREATE TABLE IF NOT EXISTS reservations (id uuid PRIMARY KEY, task_id uuid UNIQUE NOT NULL REFERENCES tasks(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), amount numeric(30,7) NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deliveries (id uuid PRIMARY KEY, task_id uuid UNIQUE NOT NULL REFERENCES tasks(id), content text NOT NULL, sha256 text NOT NULL, references_json jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operations (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), task_id uuid REFERENCES tasks(id), kind text NOT NULL, amount numeric(30,7) NOT NULL, asset_network text NOT NULL, asset_code text NOT NULL, asset_issuer text NOT NULL, destination text NOT NULL, status text NOT NULL, quote_expires_at timestamptz, transaction_hash text UNIQUE, confirmed_ledger bigint, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys (workspace_id uuid NOT NULL REFERENCES workspaces(id), route text NOT NULL, key text NOT NULL, request_digest text NOT NULL, response_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,route,key));
CREATE TABLE IF NOT EXISTS outbox_jobs (id uuid PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS receipt_events (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), operation_id uuid REFERENCES operations(id), event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
